#include <bits/stdc++.h>

using namespace std;

const int MAX_LIMIT = 2345678;

double input_probs[123], probs_array[123];
double dp_vals[MAX_LIMIT];
double output[123];
int index_map[123];
int count_bits[MAX_LIMIT];

int main() {
    int total_input, max_k_value;
    scanf("%d %d", &total_input, &max_k_value);
    int valid_count = 0;
    for (int i = 0; i < total_input; i++) {
        scanf("%lf", input_probs + i);
        if (input_probs[i] > 1e-4) {
            index_map[valid_count] = i;
            probs_array[valid_count] = input_probs[i];
            valid_count++;
        }
    }
    max_k_value = min(max_k_value, valid_count);
    count_bits[0] = 0;
    for (int mask = 1; mask < (1 << valid_count); mask++) {
        count_bits[mask] = count_bits[mask & (mask - 1)] + 1;
    }
    for (int mask = 0; mask < (1 << valid_count); mask++) {
        dp_vals[mask] = 0.0;
    }
    for (int i = 0; i < total_input; i++) {
        output[i] = 0.0;
    }
    dp_vals[0] = 1.0;
    for (int mask = 0; mask < (1 << valid_count); mask++) {
        if (count_bits[mask] == max_k_value) {
            for (int j = 0; j < valid_count; j++) {
                if (mask & (1 << j)) {
                    output[index_map[j]] += dp_vals[mask];
                }
            }
            continue;
        }
        double total_prob_sum = 0;
        for (int j = 0; j < valid_count; j++) {
            if (mask & (1 << j)) continue;
            total_prob_sum += probs_array[j];
        }
        double ratio = dp_vals[mask] / total_prob_sum;
        for (int j = 0; j < valid_count; j++) {
            if (mask & (1 << j)) continue;
            dp_vals[mask | (1 << j)] += probs_array[j] * ratio;
        }
    }
    for (int i = 0; i < total_input; i++) {
        if (i > 0) cout << " ";
        printf("%.17f", output[i]);
    }
    printf("\n");
    return 0;
}
